const input = $input.first().json;

let context = input.normalized_context;

if (typeof context === "string") {
  context = JSON.parse(context);
}

if (!input.run_id) throw new Error("Missing run_id");
if (!input.project_page_id) throw new Error("Missing project_page_id");
if (!context) throw new Error("Missing normalized_context");

const plannerInput = {
  run_id: input.run_id,
  project_id: input.project_page_id,
  intake_page_id: input.intake_page_id,

  project: context.project,
  stats: context.stats,
  document_index: context.document_index,
  sources: context.sources,

  instruction_context: {
    expected_output: "implementation plan for an AI-powered project intake automation system",
    avoid: [
      "generic research tasks",
      "empty architecture",
      "empty workflow design",
      "invented external tools",
      "markdown output"
    ]
  }
};

return [
  {
    json: {
      run_id: input.run_id,
      intake_page_id: input.intake_page_id,
      project_page_id: input.project_page_id,
      normalized_context: context,
      prompt_input: JSON.stringify(plannerInput)
    }
  }
];

const raw =
  $json.output ||
  $json.text ||
  $json.content ||
  $json.message ||
  JSON.stringify($json);

const input = $('Prepare Planner Prompt').first().json;
const context = input.normalized_context;

function parseJsonFromText(value) {
  let text = String(value).trim();

  text = text
    .replace(/^```json/i, "")
    .replace(/^```/i, "")
    .replace(/```$/i, "")
    .trim();

  const first = text.indexOf("{");
  const last = text.lastIndexOf("}");

  if (first !== -1 && last !== -1) {
    text = text.slice(first, last + 1);
  }

  return JSON.parse(text);
}

const plan = parseJsonFromText(raw);

const allowedStages = [
  "Discovery",
  "Design",
  "Development",
  "Testing",
  "Production",
  "Optimization"
];

const allowedStatuses = ["Not started", "In progress", "Done"];
const allowedPriorities = ["Low", "Medium", "High", "Urgent"];
const allowedEfforts = ["Small", "Medium", "Large"];

function normalizeValue(value, allowed, fallback) {
  if (!value) return fallback;
  const clean = String(value).trim();
  return allowed.includes(clean) ? clean : fallback;
}

function normalizeArray(value) {
  if (!value) return [];
  if (Array.isArray(value)) return value.map(v => String(v).trim()).filter(Boolean);
  return [String(value).trim()].filter(Boolean);
}

function cleanText(value) {
  if (!value) return "";
  return String(value).trim();
}

const runId = plan.run_id || input.run_id;
const projectId = plan.project_id || input.project_page_id;
const intakePageId = plan.intake_page_id || input.intake_page_id;
const fallbackDeadline = context.project?.deadline || "";

const rawTasks = Array.isArray(plan.tasks) ? plan.tasks : [];

const tasks = rawTasks.map((task, index) => {
  const stage = normalizeValue(task.task_stage, allowedStages, "Discovery");
  const name = cleanText(task.task_name || `${stage} Task ${index + 1}`);

  return {
    run_id: runId,
    project_page_id: projectId,
    intake_page_id: intakePageId,

    task_key: `${runId}_${index + 1}_${name}`
      .toLowerCase()
      .replace(/[^\w]+/g, "_")
      .replace(/^_+|_+$/g, ""),

    task_name: name,
    task_description: cleanText(task.task_description),
    task_stage: stage,
    task_status: normalizeValue(task.task_status, allowedStatuses, "Not started"),
    priority: normalizeValue(task.priority, allowedPriorities, "Medium"),
    effort_level: normalizeValue(task.effort_level, allowedEfforts, "Medium"),
    deadline: task.deadline || fallbackDeadline || ""
  };
});

const normalizedPlan = {
  run_id: runId,
  project_id: projectId,
  intake_page_id: intakePageId,

  project_summary: cleanText(plan.project_summary),
  business_problem: cleanText(plan.business_problem || context.project?.business_problem),
  desired_outcome: cleanText(plan.desired_outcome),
  technical_architecture: cleanText(plan.technical_architecture),
  workflow_design: cleanText(plan.workflow_design),

  tools_and_systems: normalizeArray(plan.tools_and_systems),
  apis_and_integrations: normalizeArray(plan.apis_and_integrations),
  data_objects: normalizeArray(plan.data_objects),
  risks: normalizeArray(plan.risks),
  assumptions: normalizeArray(plan.assumptions),
  missing_information: normalizeArray(plan.missing_information),

  implementation_phases: Array.isArray(plan.implementation_phases)
    ? plan.implementation_phases
    : [],

  tasks,
  task_count: tasks.length,

  planning_status: normalizeArray(plan.missing_information).length > 0
    ? "NEEDS_CLARIFICATION"
    : "AI_PLANNED"
};

return [{ json: normalizedPlan }];

const plan = $('Parse AI Plan').first().json;

if (!Array.isArray(plan.tasks) || plan.tasks.length === 0) {
  throw new Error("AI plan produced no tasks");
}

return plan.tasks.map((task, index) => ({
  json: {
    ...task,
    task_order: index + 1
  }
}));

const plan = $('Parse AI Plan').first().json;
const saved = $('Save AI Plan').first().json;

return [
  {
    json: {
      run_id: saved.run_id,
      intake_page_id: saved.intake_page_id,
      project_page_id: saved.project_page_id,
      status: 'Discovery',
      project_status: 'Discovery',
      task_count: plan.task_count,
      ai_plan: plan
    }
  }
];
